    /*
     * Add to the Streams
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	TelemetrySchema
     */
    public TelemetrySchema addToStreams( UUID parentId, TelemetryStream addTo ) {
	    LOGGER.info("handling AssignStreamsToTelemetrySchemaEvent - " );
	    
	    TelemetrySchema parentEntity = repository.findById(parentId).get();
	    TelemetryStream child = registry.project( TelemetryStream.class, addTo.getTelemetryStreamId());
	    
	    parentEntity.getStreams().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Streams
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	TelemetrySchema
     */
	public TelemetrySchema removeFromStreams( UUID parentId, TelemetryStream removeFrom ) {
	    LOGGER.info("handling RemoveStreamsFromTelemetrySchemaEvent " );
	
	    TelemetrySchema parentEntity = repository.findById(parentId).get();
	    TelemetryStream child = registry.project( TelemetryStream.class, removeFrom.getTelemetryStreamId());
	    
	    parentEntity.getStreams().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



